-- Eastbound 3PL Index: public freight rate and US tariff data
-- Rates as of 2026-10-01, tariffs as of 2026-10-05. Generated by build.py; edit data/*.json instead.

CREATE TABLE freight_rates (lane_origin VARCHAR(8), lane VARCHAR(120), mode VARCHAR(16), usd DECIMAL(12,2), unit VARCHAR(40),
  observed DATE, kind VARCHAR(40), source VARCHAR(120), url VARCHAR(300), used_in_site BOOLEAN);

CREATE TABLE tariff_countries (code VARCHAR(4) PRIMARY KEY, name VARCHAR(40), forced_labor_301_pct DECIMAL(5,2));

CREATE TABLE tariff_products (hts VARCHAR(12), sector VARCHAR(20), name VARCHAR(80), mfn_pct DECIMAL(5,2),
  china_301_pct DECIMAL(5,2), section_232_pct DECIMAL(5,2), adcvd_possible BOOLEAN, note VARCHAR(300));

CREATE TABLE customs_fees (fee VARCHAR(8), rate_pct DECIMAL(7,4), min_usd DECIMAL(10,2), max_usd DECIMAL(10,2), note VARCHAR(120));
